INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-01','物理','single','下列计时数据指时间间隔的是（ ）','{"A": "北京时间2026年5月24日23时08分，搭载神舟二十三号载人飞船的长征二号F遥二十三运载火箭在酒泉卫星发射中心点火发射", "B": "某同学在校运动会上110m跨栏成绩是14.10s", "C": "一辆汽车在第10s末开始加速行驶", "D": "我们12时15分开始吃午饭"}','B','A：2026年5月24日23时08分是时刻，错；B：14.10s是时间间隔，对；C：第10s末是时刻，错；D：12时15分是时刻，错。故选B。',4,'时间间隔 vs 时刻','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-02','物理','single','下列情形中，可以把人或物体看成质点的是（ ）','{"A": "研究地球的自转", "B": "研究跳水运动员的空中姿态", "C": "观察苏炳添百米赛跑的起跑动作", "D": "测量动车从宁德站到上海站的时间"}','D','A：研究地球自转需考虑地球大小形状，不能看成质点；B：研究跳水姿态需考虑身体大小形状，不能；C：观察起跑动作需考虑身体，不能；D：测量动车运行时间可忽略动车大小形状，可以看成质点。故选D。',4,'质点模型','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-03','物理','single','这是宋代诗人陈与义的一首诗："飞花两岸照船红，百里榆堤半日风，卧看满天云不动，不知云与我俱东"，在诗人看来云是不动的，他选择的参照物是（ ）','{"A": "岸边的江堤", "B": "江边的树", "C": "树上的飞花", "D": "诗人的小船"}','D','"不知云与我俱东"说明相对于地面，诗人与云都向东运动、运动状态相同、相对静止。诗人以自己乘坐的小船为参照物看云，就会出现"卧看满天云不动"的效果。故选D。',4,'参考系','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-04','物理','single','【注：原卷中加速度数值转换丢失，据答案反推为5m/s²】航空母舰上有帮助飞机起飞的弹射系统，已知某战斗机离开弹射系统后，在跑道上做加速度大小为5m/s²的匀加速直线运动，战斗机在跑道上自主滑行100m时起飞，飞机离开跑道的速度大小为55m/s，则弹射系统赋予战斗机的初速度大小为（ ）','{"A": "35m/s", "B": "40m/s", "C": "45m/s", "D": "50m/s"}','C','由 v²−v₀²=2ax 得 v₀=√(v²−2ax)=√(55²−2×5×100)=√(3025−1000)=√2025=45m/s。故选C。',4,'匀变速直线运动速度与位移关系','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-05','物理','multi','关于速度和加速度的关系，下列说法中正确的是（ ）','{"A": "物体的加速度等于零，速度一定等于零", "B": "物体的加速度越大，速度一定越大", "C": "物体的加速度越大，速度一定改变越快", "D": "物体的加速度增大，速度可能减小"}','CD','A：光滑平面上匀速直线运动的滑块，加速度为零但速度不为零，错；B：a=Δv/Δt，加速度大小与速度大小无关，错；C：加速度是描述速度变化快慢的物理量，对；D：当加速度方向与速度方向相反时，加速度增大、速度减小，对。故选CD。',6,'速度与加速度的关系','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-06','物理','multi','【注：原卷中部分数字转换丢失，据答案反推复原：路程5.4km、用时1h、M、N直线距离1.8km】一游客在武夷山九曲溪乘竹筏漂流，途经双乳峰附近的M点和玉女峰附近的N点。已知该游客从M点漂流到N点的路程为5.4km，用时1h，M、N间的直线距离为1.8km，则从M点漂流到N点的过程中（ ）','{"A": "该游客的位移大小为5.4km", "B": "该游客的平均速率为5.4km/h", "C": "该游客的平均速度大小为1.8m/s", "D": "若以所乘竹筏为参考系，玉女峰在这段时间内的平均速度大小为0.5m/s"}','BD','A：位移是M→N的有向线段，大小为1.8km≠5.4km，错；B：平均速率=路程/时间=5.4km/1h=5.4km/h，对；C：平均速度=位移/时间=1.8km/1h=1.8km/h=0.5m/s≠1.8m/s，错；D：以竹筏为参考系，玉女峰相对竹筏运动，位移大小1.8km、时间1h，平均速度大小0.5m/s，对。故选BD。',6,'位移/路程、平均速度/平均速率、参考系','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-07','物理','multi','从静止开始做匀加速直线运动的物体，第1s内通过的位移为0.5m，则（ ）','{"A": "第1s末物体的速度为1m/s", "B": "第1s末物体的速度为2m/s", "C": "第1s内物体的平均速度为1m/s", "D": "物体的加速度为1m/s²"}','AD','由 x=½at² 得 0.5=½×a×1²，a=1m/s²（D对）；第1s末速度 v=at=1×1=1m/s（A对、B错）；第1s内平均速度=x/t=0.5/1=0.5m/s（C错）。故选AD。',6,'初速为零的匀加速直线运动规律','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-08','物理','multi','如图所示，光滑斜面AE被分成长度相等的四段（AB=BC=CD=DE），一个物体由A点静止释放后做匀加速直线运动，下面结论中正确的是（ ）','{"A": "经过每一部分时，其速度增量均相同", "B": "物体到达B、C、D、E各点的速度大小之比为1:√2:√3:2", "C": "物体通过AB、BC、CD、DE段所需的时间之比为1:(√2−1):(√3−√2):(2−√3)", "D": "若该物体从A点运动到E点共用时4s，则物体在第2s末的速度等于B点速度"}','BD','B：由 v²=2ax（初速为0），v∝√x，vB:vC:vD:vE=1:√2:√3:2，对；C：通过连续相等位移时间之比确为1:(√2−1):(√3−√2):(2−√3)，但原卷该选项表述有误，按详解判错；A：每段速度增量Δv=aΔt，各段时间不同，增量不同，错；D：AB:BE=1:3，B为中间时刻（总时间4s），2s末速度=中间时刻速度=vB，对。故选BD。',6,'初速为零匀加速直线运动的比例推论','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-09','物理','fill','一物体做直线运动，它经过前一半路程的平均速度为6m/s，经过后一半路程的平均速度为9m/s，则物体全过程的平均速度为____m/s。如果它经过前一半时间的平均速度为4m/s，经过后一半时间的平均速度为8m/s，则物体全过程的平均速度为____m/s。',NULL,'["7.2", "6"]','[1]设总路程为s，前一半路程用时 t1=(s/2)/6=s/12，后一半用时 t2=(s/2)/9=s/18，全程时间 t=s/12+s/18=5s/36，全程平均速度=s/t=7.2m/s。[2]设总时间为t，前一半时间路程=4×(t/2)=2t，后一半=8×(t/2)=4t，总路程=6t，平均速度=6t/t=6m/s。',4,'平均速度（路程/时间两种情形）','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-10','物理','fill','某物体沿x轴做直线运动，其位置坐标随时间的变化如图乙所示（x-t图像：t=0时x=2m；0~1s直线上升到x=3m；1~3s保持x=3m不动；3~4s直线下降到x=0；图像据详解数据反推）。在第3s末的坐标为 x3=____m，第4s内物体坐标变化量 Δx=____m；在第1s内物体平均速度为____m/s，在第4s内物体平均速度为____m/s；在前4s内通过的路程是____m。',NULL,'["3", "−3", "1", "−3", "4"]','[1]第3s末坐标 x3=3m。[2]第4s内坐标变化量 Δx=x末−x初=0−3=−3m（注意符号）。[3]第1s内平均速度 v1=Δx1/t=(3−2)/1=1m/s。[4]第4s内平均速度 v2=(0−3)/1=−3m/s。[5]前4s路程 s=(3−2)+(3−0)=4m（先上后下，路程相加）。',10,'x-t图像','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-11','物理','exp','【注：原卷中数字转换丢失，据答案反推复原】用气垫导轨和光电门测物体的加速度。数字毫秒计记录了遮光板通过第一个光电门的时间为0.125s，通过第二个光电门的时间为0.020s，遮光板从开始遮住第一个光电门到开始遮住第二个光电门的时间为3.00s，已知遮光板的宽度为1.00cm。分别求出滑块通过第一个光电门的速度大小、第二个光电门的速度大小，以及滑块的加速度（结果均保留两位小数）。',NULL,'["0.08", "0.50", "0.14"]','遮光板通过光电门时间极短，平均速度可视为瞬时速度，v=d/Δt。[1]v1=0.0100/0.125=0.08m/s。[2]v2=0.0100/0.020=0.50m/s。[3]a=(v2−v1)/Δt=(0.50−0.08)/3.00=0.14m/s²。',6,'光电门测瞬时速度、加速度','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-12','物理','exp','某同学用如图所示装置研究小车运动的速度随时间变化的规律（纸带图略）。(1)电火花打点计时器使用的电源为____（选填"直流220V"或"交流220V"）电源。(2)实验打出的纸带上各点为计数点，相邻两计数点间还有四个计时点未标出，打点计时器所接电源的频率为50Hz，根据打出的纸带计算出打B点时小车的速度____m/s，小车运动的加速度____m/s²（结果均保留2位有效数字；关键数据：计数点间隔T=0.1s，详解取纸带数据用逐差法）。',NULL,'["交流220V", "0.81", "2.0"]','(1)电火花打点计时器使用交流220V电源。(2)打点周期0.02s，相邻计数点间还有四个计时点未标出，故计数点时间间隔 T=5×0.02s=0.1s。打B点速度用B点前后两段位移的平均：vB=(xAB+xBC)/(2T)=0.81m/s。加速度用逐差法：a=[(9.10−7.10)×10⁻²]/(0.1²)m/s²=2.0m/s²（数据引自详解）。',6,'打点计时器纸带、逐差法','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-13','物理','calc','一质量为0.4kg的足球，以10m/s的速度迎面飞来，足球守门员将球以8m/s的速度反向踢出，守门员与球接触的时间为0.1s，求：(1)足球在与守门员接触的这段时间内的速度的变化量大小；(2)足球在与守门员接触的这段时间内的平均加速度大小。',NULL,'["18m/s", "180m/s²"]','取足球返回的方向为正方向（先写正方向！）。(1)速度的变化量 Δv=v2−v1=8−(−10)=18m/s（2分），=18m/s（1分）。答：足球速度的变化量大小为18m/s（1分）。注意迎面飞来取负，反向踢回两者相加不是相减。(2)加速度 a=Δv/t=18/0.1=180m/s²（2分），=180m/s²（1分）。答：足球加速度大小180m/s²（1分）。',8,'速度变化量的矢量性、加速度定义式','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-14','物理','calc','一摩托车由静止开始在平直的公路上行驶，其运动过程的v-t图像如图所示（v-t图像：0~20s从0匀加速到30m/s；20~45s保持30m/s匀速；45~75s匀减速到0；后段据详解梯形面积反推）。求：(1)摩托车在0~20s这段时间的加速度大小；(2)摩托车在0~75s这段时间的平均速度大小。',NULL,'["1.5m/s²", "20m/s"]','(1)v-t图像斜率=加速度：a=Δv/Δt=30/20=1.5m/s²（2分），=1.5m/s²（1分）。答：0~20s加速度大小为1.5m/s²（1分）。(2)v-t图像面积=位移：x=½×(25+75)×30=1500m（2分，梯形：上底25s匀速段、下底75s总时间）。平均速度 v=x/t=1500/75=20m/s（2分）。',10,'v-t图像（斜率、面积）','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('phy-15','物理','calc','【注：原卷中初速度与加速度数值转换丢失，据详解反推复原为18m/s、6m/s²】以18m/s的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为6m/s²。求：(1)汽车在刹车1s末的速度；(2)汽车在刹车2s内的位移；(3)汽车在刹车4s内的位移。',NULL,'["12m/s", "24m", "27m"]','取汽车初速度方向为正方向。刹车问题第一步：先算停止时间 t₀=v₀/a=18/6=3s！(1)v=v₀+at=18−6×1=12m/s（2分），=12m/s（1分）。答：刹车1s末速度大小为12m/s，方向与初速度相同（1分）。(2)t=2s<t₀，用 x=v₀t−½at²=18×2−½×6×4=36−12=24m（3分），=24m（1分）。答：刹车2s内位移24m（1分）。(3)t=4s>t₀，汽车3s已停住，刹车4s内的位移=3s内的位移：x=18×3−½×6×9=54−27=27m（2分），=27m（1分）。答：位移大小27m（1分）。陷阱：直接代t=4s会得到24m的错误答案。',16,'刹车陷阱（先算停止时间）','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-01','数学','single','下列关系中，正确的有（ ）','{"A": "∅∈{0}", "B": "√2∈Q", "C": "Q⊆Z", "D": "−2∈Z"}','D','A错：∅是集合不是元素，应为∅⊆{0}；B错：√2是无理数，√2∉Q；C错：Q⊄Z，如1/2∈Q但1/2∉Z；D对：−2是整数。',5,'集合符号（∈/⊆）','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-02','数学','single','已知全集U={0,1,2,3,4}，集合A={0,2,4}，集合B={2,3,4}，则如图所示的阴影部分表示的集合为（ ）。（图中阴影部分为矩形内除A、B两圆相交部分之外的所有区域，即A∩B在全集U中的补集）','{"A": "{0,2,3,4}", "B": "{0,1,3}", "C": "{2,4}", "D": "{1}"}','B','A∩B={2,4}，阴影部分为∁U(A∩B)={0,1,3}。',5,'Venn图与集合运算','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-03','数学','single','已知命题p：∀x>0，x²−1≥0，则命题p的否定为（ ）','{"A": "∀x≤0，x²−1<0", "B": "∀x>0，x²−1<0", "C": "∃x₀≤0，x₀²−1<0", "D": "∃x₀>0，x₀²−1<0"}','D','全称量词命题的否定：∀改∃，结论否定，量词的范围（x>0）保持不变。',5,'全称量词命题的否定','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-04','数学','single','不等式(x−1)/(x−2)≥0的解集为（ ）','{"A": "{x|1≤x≤2}", "B": "{x|x≤1或x≥2}", "C": "{x|1≤x<2}", "D": "{x|x>2或x≤1}"}','D','等价于{(x−1)(x−2)≥0, x−2≠0}，解得x>2或x≤1。注意分母不为零，x=2要舍去。',5,'分式不等式','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-05','数学','single','已知集合A={x|0≤x<4, x∈N*}，则集合A的子集的个数为（ ）','{"A": "32", "B": "16", "C": "8", "D": "4"}','C','N*是正整数集，A={1,2,3}，共3个元素，子集个数为2³=8。',5,'子集个数','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-06','数学','single','已知p：0<x<2，q：−1<x<3，则q是p的（ ）','{"A": "充分不必要条件", "B": "必要不充分条件", "C": "充要条件", "D": "既不充分也不必要条件"}','B','p⇒q（(0,2)⊂(−1,3)），但q⇏p，所以p是q的充分不必要条件，即q是p的必要不充分条件。',5,'充分必要条件','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-07','数学','single','已知集合A={x|a−1≤x≤2a+1}，B={x|−3≤x≤3}，且A∩B=A，则实数a的取值范围是（ ）','{"A": "[−2,1]", "B": "(−2,1)", "C": "(−∞,−2)", "D": "(−∞,1]"}','D','A∩B=A即A⊆B。若A=∅（a<−2）显然成立；若A≠∅，需a−1≥−3且2a+1≤3，得−2≤a≤1。合并得a≤1。易漏点：A为空集的情形。',5,'集合包含关系求参数','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-08','数学','single','已知x>0，y>0，且x+y=5，若4/(x+1)+1/(y+2)≥2m+1恒成立，则实数m的取值范围是（ ）','{"A": "m≤1/16", "B": "m≤2/5", "C": "m≤1/2", "D": "m≤1/4"}','A','x+1+y+2=8。4/(x+1)+1/(y+2)=(1/8)[4/(x+1)+1/(y+2)][(x+1)+(y+2)]≥(1/8)(5+2√4)=9/8，当且仅当x=13/3、y=2/3时取等。由2m+1≤9/8得m≤1/16。',5,'基本不等式与恒成立','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-09','数学','multi','设集合A={−1, x+2, x²−2x}，且3∈A，则x的值可以为（ ）','{"A": "3", "B": "−3", "C": "−1", "D": "1"}','AC','若x+2=3得x=1，此时A={−1,3,−1}违背互异性，舍去；若x²−2x=3得x=3或x=−1，x=3时A={−1,5,3}成立，x=−1时A={−1,1,3}成立。故x=3或x=−1。（注：答案整理表备注误作x=−3，已据原卷核对更正。）',6,'集合元素的互异性','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-10','数学','multi','十六世纪中叶，英国数学家雷科德在《砺智石》一书中首先把“=”作为等号使用，后来英国数学家哈利奥特引入“<”和“>”符号，对不等式的发展影响深远。若a>b>1，c>0，则下列不等式一定成立的是（ ）。','{"A": "a²−bc>b²−ac", "B": "c≥(b+ac)/(a+bc)", "C": "a/b>(a+c)/(b+c)", "D": "bc/a>ac/b"}','AC','A：a²−b²>bc−ac即(a−b)(a+b+c)>0，成立；B：等价于c²≥1，c>0不能保证，取c=0.5即为反例；C：等价于ac>bc即a>b，成立；D：等价于b²>a²，与a>b矛盾。',6,'不等式的性质','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-11','数学','multi','已知正数a，b满足2a+b=1，则（ ）','{"A": "ab的最大值为1/8", "B": "1/a+1/b的最小值为4", "C": "√(2a)+√b的最小值为√2", "D": "a²+b²的最小值为1/5"}','AD','A：ab=(2a·b)/2≤((2a+b)/2)²/2=1/8；B：1/a+1/b的最小值为3+2√2≠4；C：令u=√(2a)、v=√b，则u²+v²=1，u+v>1无最小值（下确界为1）；D：由柯西不等式(4+1)(a²+b²)≥(2a+b)²=1，得a²+b²≥1/5。',6,'基本不等式求最值','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-12','数学','fill','已知f(x)={x²+1, x≥0; −x+1, x<0}，则f[f(−2)]=______。',NULL,'10','先算内层：f(−2)=−(−2)+1=3；再算外层：f(3)=3²+1=10。关键：根据自变量的范围选对解析式。',5,'分段函数求值','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-13','数学','fill','已知实数x，y满足−4≤x−y≤−1，−1≤4x−y≤5，则t=9x−y的取值范围是______。',NULL,'[−1,20]','待定系数：设9x−y=a(x−y)+b(4x−y)，解得a=−5/3，b=8/3。则t=−5/3(x−y)+8/3(4x−y)。由−4≤x−y≤−1得5/3≤−5/3(x−y)≤20/3，由−1≤4x−y≤5得−8/3≤8/3(4x−y)≤40/3，相加得−1≤t≤20。',5,'不等式范围（待定系数法）','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-14','数学','fill','已知A={y|y=x²−2x−8, x∈R}，B={x|y=√(x+9)}，那么集合A与B的关系为______。',NULL,'B=A','A是二次函数的值域：y=(x−1)²−9≥−9，即A={y|y≥−9}；B是函数y=√(x+9)的定义域：x+9≥0即B={x|x≥−9}。作为实数集两者都是[−9,+∞)，故B=A。易错点：代表元素y/x只是记号，不影响集合本身。',5,'集合的表示（值域/定义域）','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-15','数学','solve','已知集合A={x|−1≤x<3}，B={x|1<3x−5<16}，（1）求A∪B；（2）求A∩B；（3）求∁R A∩B。',NULL,'（1）A∪B={x|−1≤x<7}；（2）A∩B={x|2<x<3}；（3）∁R A∩B={x|3≤x<7}','关键步骤：先化简B：1<3x−5<16得2<x<7。（1）并集取两集合的合并：{x|−1≤x<7}；（2）交集取公共部分：{x|2<x<3}；（3）先求补集∁R A={x|x<−1或x≥3}，再与B取交得{x|3≤x<7}。注意端点开闭。',13,'集合的交并补运算','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-16','数学','solve','已知函数f(x)=√(3−x)+1/√(x+2)的定义域为集合A，B={x|x<a}。（1）求集合A；（2）若A⊆B，求a的取值范围。',NULL,'（1）A={x|−2<x≤3}；（2）a>3，即(3,+∞)','（1）√(3−x)有意义需3−x≥0即x≤3；1/√(x+2)有意义需x+2>0即x>−2（分母不为零且根号内为正）。取交集得A={x|−2<x≤3}。（2）A⊆B={x|x<a}，A中最大元素x=3必须满足3<a，故a>3。',15,'函数定义域与集合包含','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-17','数学','solve','已知函数f(x)=mx²−mx−1。（1）若m=1/2，求不等式f(x)<0的解集；（2）若关于x的不等式f(x)<0对一切x∈R恒成立，求实数m的取值范围。',NULL,'（1）{x|−1<x<2}；（2）{m|−4<m≤0}','（1）m=1/2时化为x²−x−2<0，因式分解(x+1)(x−2)<0，解得−1<x<2。（2）m=0时−1<0恒成立；m≠0时需开口向下（m<0）且判别式Δ=m²+4m<0，解得−4<m<0。合并得−4<m≤0。易漏点：m=0的单独讨论。',15,'一元二次不等式恒成立','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-18','数学','solve','如图，某人计划用篱笆围成一个一边靠墙（墙足够长）的矩形菜园。设菜园的长为x米，宽为y米。（1）若菜园面积为36平方米，则x，y为何值时，所用篱笆总长最小？（2）若使用的篱笆总长为30米，把菜园面积S表示为长x的函数：①当菜园面积不小于100平方米时，求x的取值范围；②求函数S(x)的值域，并指出面积最大时x，y的值。',NULL,'（1）x=6√2米，y=3√2米时篱笆总长最小；（2）S(x)=−x²/2+15x（0<x<30）；①10≤x≤20；②值域(0,225/2]，x=15、y=7.5时面积最大225/2','（1）xy=36，篱笆总长为x+2y≥2√(2xy)=12√2，当且仅当x=2y即x=6√2、y=3√2时取等。（2）由x+2y=30得y=(30−x)/2，S(x)=x(30−x)/2=−x²/2+15x（0<x<30）。①S≥100化为x²−30x+200≤0，分解(x−10)(x−20)≤0，得10≤x≤20。②配方S(x)=−(x−15)²/2+225/2，开口向下，对称轴x=15在定义域内，故Smax=225/2，此时y=7.5；x→0或30时S→0，值域为(0,225/2]。',17,'基本不等式应用与二次函数','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('math-19','数学','solve','已知∃x∈R，2mx²+mx+1/8<0，记实数m的取值范围为集合M。（1）求集合M；（2）已知集合N={x|x²+(1−a)x−a>0}，若“x∈N”是“x∈M”的充分不必要条件，求实数a的取值范围。',NULL,'（1）M={m|m<0或m>1}；（2）a≥1','（1）m=0时1/8<0不成立；m<0时开口向下，必存在x使不等式成立；m>0时需Δ=m²−m>0，解得m>1。综上M={m|m<0或m>1}。（2）“x∈N是x∈M的充分不必要条件”即N⫋M。由x²+(1−a)x−a>0得(x−a)(x+1)>0。分类：a=−1时N={x|x≠−1}⊄M；a<−1时N={x|x<a或x>−1}⊄M；a>−1时N={x|x<−1或x>a}，要N⊂M需a≥1。综上a≥1。',17,'存在量词命题与充分必要条件','高一上第一次月考');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-01','化学','single','下列做法符合实验安全要求的是（ ）','{"A": "剩余的钠块放回原试剂瓶", "B": "金属钠着火时使用泡沫灭火器灭火", "C": "浓硫酸与氢氧化钠固体放在同一实验橱内", "D": "新制氯水保存在棕色广口瓶中，置于避光阴凉处"}','A','A 对：钠是活泼金属，剩余钠块应放回原试剂瓶，不能随意丢弃；B 错：钠着火不能用泡沫灭火器（泡沫中的水和二氧化碳都会与钠反应），应用沙土扑灭；C 错：酸和碱应分开存放；D 错：氯水是液体，应保存在棕色细口瓶中，不是广口瓶。故选 A。',4,'化学实验安全','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-02','化学','single','构建化学基本观念是学好化学的基础。下列认识错误的是（ ）','{"A": "元素观：物质是由元素组成的", "B": "分类观：H2O 和 Al2O3 均是氧化物", "C": "守恒观：1g 碳与 1g 氧气充分反应，生成 2g 二氧化碳", "D": "转化观：化学变化有新物质生成，其本质是原子的重新组合"}','C','A 对：物质都是由元素组成的；B 对：H2O 和 Al2O3 都是由两种元素组成、其中一种是氧元素的化合物，属于氧化物；C 错：1g 碳完全燃烧需要约 2.67g 氧气，1g 氧气只够生成约 1.375g 二氧化碳（氧气不足、碳有剩余），不可能生成 2g；D 对：化学变化的本质就是原子的重新组合。故选 C。',4,'化学基本观念','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-03','化学','single','NA 表示阿伏加德罗常数的值，下列叙述正确的是（ ）','{"A": "22g CO2 所含有的分子数为 0.5NA", "B": "含 0.1mol BaCl2 的溶液中 Cl⁻ 数为 0.1NA", "C": "11.2L CO2 所含有的分子数为 0.5NA", "D": "7.8g Na2O2 中含有的离子总数为 0.4NA"}','A','A 对：22g CO2 为 0.5mol，分子数为 0.5NA；B 错：0.1mol BaCl2 电离出 0.2mol Cl⁻，应为 0.2NA；C 错：没说标准状况，11.2L 气体的物质的量不一定是 0.5mol；D 错：7.8g Na2O2 为 0.1mol，含 0.2mol Na⁺ 和 0.1mol O₂²⁻，离子总数为 0.3NA。故选 A。',4,'阿伏加德罗常数','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-04','化学','single','下列关于钠及其化合物的说法正确的是（ ）','{"A": "Na2O 久置于空气中，最终转化为 NaHCO3", "B": "Na2O 与 Na2O2 都能和水反应生成碱，它们都是碱性氧化物", "C": "Na2CO3 溶液能与酸溶液反应，但不能与碱溶液反应", "D": "Na 投入 MgCl2 溶液中生成白色沉淀和无色气体"}','D','A 错：Na2O 久置空气中先变成 NaOH，最终变成 Na2CO3，不是 NaHCO3；B 错：Na2O2 与水反应除生成碱外还有 O2 生成，不属于碱性氧化物；C 错：Na2CO3 能与澄清石灰水等碱反应生成 CaCO3 沉淀；D 对：Na 先与水反应生成 NaOH 和 H2，NaOH 再与 MgCl2 反应生成白色 Mg(OH)2 沉淀。故选 D。',4,'钠及其化合物','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-05','化学','single','下列有关实验现象与分析或结论都正确的是（ ）','{"A": "光照新制氯水有气泡冒出——氯水中含有 Cl2，光照 Cl2 逸出", "B": "氯水中加入 NaOH 溶液，氯水黄绿色消失——氯水中有 HClO 分子存在", "C": "向镁粉中加入久置的氯水，有无色无味的气体产生——产生的气体是 H2", "D": "向氯水中加入盐酸酸化，再加入硝酸银溶液产生白色沉淀——氯水中有 Cl⁻ 存在"}','C','A：现象对但结论错——光照氯水冒气泡是因为 HClO 见光分解放出 O2，不是 Cl2 逸出；B：黄绿色消失只能证明有 Cl2（被 NaOH 吸收了），不能证明有 HClO；C 对：久置的氯水相当于稀盐酸，Mg 与盐酸反应放出无色无味的 H2；D：加盐酸酸化引入了 Cl⁻，再加 AgNO3 有沉淀不能证明原氯水中有 Cl⁻。故选 C。',4,'实验现象与结论','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-06','化学','single','温度、压强相同时，等体积的两容器内，一个盛 CO2，另一个盛 H2，则两容器内所盛气体相比，下列结论一定不正确的是（ ）','{"A": "分子个数比为 1∶1", "B": "密度比为 22∶1", "C": "原子个数比为 1∶1", "D": "质量比为 22∶1"}','C','同温同压同体积 → 两容器气体分子数相等。A 对：分子数比 1∶1；B 对：密度比 = 摩尔质量比 = 44∶2 = 22∶1；C 错：CO2 每个分子 3 个原子、H2 每个分子 2 个原子，原子数比应为 3∶2，所以"1∶1"一定不正确；D 对：质量比 = 44∶2 = 22∶1。故选 C。',4,'阿伏加德罗定律','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-07','化学','single','下列关于氯气和氯水的说法中正确的是（ ）','{"A": "红热的铁丝在 Cl2 中剧烈燃烧生成 FeCl2", "B": "氯气是一种无色、密度比空气大的有毒气体", "C": "新制氯水能杀菌消毒是因为 Cl2 有毒，能毒杀细菌", "D": "氯水放置数天后酸性增强"}','D','A 错：红热铁丝在 Cl2 中燃烧生成 FeCl3（氯气强氧化性，铁被氧化到 +3 价）；B 错：氯气是黄绿色气体，不是无色；C 错：新制氯水杀菌是因为 HClO 有强氧化性，不是 Cl2 的毒性；D 对：HClO 见光分解生成 HCl，久置的氯水酸性增强。故选 D。',4,'氯气和氯水','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-08','化学','single','下列物质所含原子数由大到小排列的是（ ）①0.5mol NH3  ②4g H2  ③标准状况下，0.3mol CO2  ④0.2mol H3PO4','{"A": "①④③②", "B": "④③②①", "C": "②③④①", "D": "②①④③"}','D','① 0.5mol NH3 含 0.5×4 = 2mol 原子；② 4g H2 为 2mol，含 2×2 = 4mol 原子；③ 0.3mol CO2 含 0.3×3 = 0.9mol 原子；④ 0.2mol H3PO4 含 0.2×8 = 1.6mol 原子。由大到小：②①④③。故选 D。',4,'物质的量计算','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-09','化学','single','下列说法正确的是（ ）','{"A": "同温、同压下，相同质量的气体都占有相同的体积", "B": "在标准状况下，1mol 任何物质的体积均为 22.4L", "C": "1mol 某气体的体积约为 22.4L，该气体所处的状况一定是标准状况", "D": "同温、同压下，相同体积的气体都含有相同数目的分子"}','D','A 错：应为"相同物质的量"的气体，不是相同质量；B 错：应为"1mol 任何气体"，不是任何物质；C 错：1mol 气体体积约为 22.4L 时，温度和压强可以有多种组合，不一定是标准状况；D 对：阿伏加德罗定律——同温同压下，相同体积的气体含有相同数目的分子。故选 D。',4,'气体摩尔体积','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-10','化学','multi','用下列实验装置进行相应实验，装置正确且能达到相应实验目的的是（ ）甲：气体依次通过饱和 NaCl 溶液、浓硫酸（长进短出）；乙：坩埚中放钠块加热；丙：稀释浓硫酸；丁：加热 Na2CO3 固体','{"A": "用图甲除去 Cl2 中的 HCl 并干燥", "B": "用图乙装置进行钠的燃烧实验", "C": "用图丙装置稀释浓硫酸", "D": "用图丁制备二氧化碳"}','AB','甲：除 Cl2 中 HCl 先经饱和食盐水（Cl2 溶解度小、HCl 极易溶），再经浓硫酸干燥，长进短出正确，能达到目的；乙：坩埚加热钠块进行钠的燃烧实验，装置正确；丙：稀释浓硫酸若在烧杯中将浓硫酸沿玻璃棒缓慢倒入水中并搅拌则正确，请对照原卷图确认容器；丁错：Na2CO3 受热不分解，不能用加热法制备 CO2。故选 AB（C 以原卷图为准）。',6,'化学实验装置','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-11','化学','fill','写出下列过程发生的化学方程式：（1）钠块在氧气中加热，生成淡黄色固体：＿＿；（2）氢气在氯气中燃烧：＿＿；（3）细铁丝在氯气中燃烧：＿＿；（4）次氯酸见光分解：＿＿；（5）工业生产漂白粉：＿＿；（6）往 CuSO4 溶液中滴加 NaOH 溶液：＿＿。',NULL,'["2Na + O2 = 【条件：△】 Na2O2", "H2 + Cl2 = 【条件：点燃】 2HCl", "2Fe + 3Cl2 = 【条件：点燃】 2FeCl3", "2HClO = 【条件：光照】 2HCl + O2↑", "2Cl2 + 2Ca(OH)2 = CaCl2 + Ca(ClO)2 + 2H2O", "CuSO4 + 2NaOH = Cu(OH)2↓ + Na2SO4"]','（1）钠在氧气中加热生成淡黄色固体 Na2O2，注意是加热不是点燃；（2）H2 在 Cl2 中燃烧生成 HCl；（3）Fe 在 Cl2 中燃烧生成 FeCl3——氯气氧化性强，铁直接被氧化到 +3 价，不生成 FeCl2；（4）HClO 见光分解是氯水久置变质、酸性增强的原因；（5）Cl2 通入石灰乳制漂白粉，有效成分是 Ca(ClO)2；（6）生成蓝色 Cu(OH)2 沉淀。条件（点燃/加热/光照）和 ↑↓ 别漏。',12,'化学方程式书写','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-12a','化学','fill','（1）1.204×10²³ 个 NO 的物质的量为＿＿mol，其 N 原子的质量为＿＿g；（2）质量相同的 SO2 和 SO3，物质的量之比是＿＿，所含氧原子个数比是＿＿。',NULL,'["0.2", "2.8", "5:4", "5:6"]','（1）1.204×10²³ ÷ 6.02×10²³ = 0.2mol；N 原子 0.2mol，质量 0.2×14 = 2.8g。（2）设质量同为 m：n(SO2) = m/64，n(SO3) = m/80，物质的量之比 = 80∶64 = 5∶4；氧原子个数比 = (5×2)∶(4×3) = 10∶12 = 5∶6。',8,'物质的量计算','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-12b','化学','fill','（3）标准状况下，3.4g NH3 与＿＿L H2S 气体含有相同数目的氢原子；（4）标准状况下，1.28g 气态氧化物 RO2 的体积为 448mL，则 R 的相对原子质量为＿＿；（5）标准状况下，V L CH4 气体中含有 a 个氢原子，则阿伏加德罗常数的值可表示为＿＿。',NULL,'["6.72", "32", "5.6a/V||22.4a/4V"]','（3）3.4g NH3 为 0.2mol，含 H 原子 0.6mol；需要 H2S 0.3mol，标况体积 0.3×22.4 = 6.72L。（4）448mL = 0.02mol，M = 1.28÷0.02 = 64g/mol，R = 64−32 = 32。（5）n(CH4) = V/22.4，H 原子数 = (4V/22.4)×NA = a，得 NA = 22.4a/4V = 5.6a/V。',6,'物质的量计算','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-13a','化学','fill','（1）Na 与水反应的化学方程式为＿＿；（2）Na2O2 与二氧化碳反应的化学方程式为＿＿；（3）Na2CO3 粉末与过量盐酸反应的化学方程式为＿＿；（4）NaH 中氢元素的化合价为＿＿价，NaH 与水反应的化学方程式为＿＿。',NULL,'["2Na + 2H2O = 2NaOH + H2↑", "2Na2O2 + 2CO2 = 2Na2CO3 + O2", "Na2CO3 + 2HCl = 2NaCl + H2O + CO2↑", "-1", "NaH + H2O = NaOH + H2↑"]','（1）钠与水剧烈反应放出 H2；（2）Na2O2 与 CO2 反应放出 O2，可作供氧剂；（3）盐酸过量，碳酸钠中的碳全部以 CO2 放出；（4）NaH 中 H 为 −1 价（活泼金属的氢化物中 H 显 −1 价），与水反应：NaH + H2O = NaOH + H2↑，生成的 H2 可燃。',10,'钠及其化合物','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-13b','化学','single','将一小块钠投入 CuSO4 溶液中，观察到的现象是（ ）①钠浮于液面上 ②熔化成小球 ③发出嘶嘶的响声，放出气体 ④有蓝色沉淀产生 ⑤析出红色的铜','{"A": "①②③", "B": "①②③④", "C": "②③④⑤", "D": "①③④⑤"}','B','Na 先与水反应：浮于液面（密度比水小）、熔成小球（熔点低、反应放热）、嘶嘶响并放出 H2；生成的 NaOH 再与 CuSO4 反应生成蓝色 Cu(OH)2 沉淀。钠不能从 CuSO4 溶液中置换出铜（它先跟水反应了），⑤错。故选 B。',2,'钠及其化合物','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-14a','化学','fill','实验室用 MnO2 与浓盐酸制备干燥纯净的氯气（B 瓶除杂、C 瓶干燥、E 烧杯 NaOH 尾气吸收）。（1）装置 A 中反应的化学方程式为＿＿；（2）B 中所盛试剂为＿＿（填序号：A.氢氧化钠溶液 B.饱和食盐水 C.浓硫酸 D.澄清石灰水），C 中所盛试剂为＿＿；（3）尾气处理反应的化学方程式为＿＿；（4）新制氯水呈黄绿色说明其中含有＿＿（填化学式）；将紫色石蕊溶液滴入氯水，观察到的现象是＿＿，说明其中含有＿＿。',NULL,'["MnO2 + 4HCl(浓) = 【条件：△】 MnCl2 + Cl2↑ + 2H2O", "B", "C", "Cl2 + 2NaOH = NaCl + NaClO + H2O", "Cl2", "先变红后褪色||变红后褪色", "H+、HClO||H+和HClO||氢离子、次氯酸||氢离子和次氯酸"]','（1）MnO2 与浓盐酸加热制 Cl2，注意盐酸要标"浓"、要加热；（2）B 用饱和食盐水除 HCl（Cl2 在其中溶解度小），C 用浓硫酸干燥——先除杂后干燥；（3）Cl2 尾气用 NaOH 溶液吸收；（4）黄绿色是 Cl2 的颜色；紫色石蕊先变红（氯水显酸性，有 H⁺）后褪色（HClO 的漂白性），说明同时含有 H⁺ 和 HClO。',10,'氯气的实验室制备','化学专题练习卷（2026-10-19）');
INSERT INTO questions(id,subject,type,stem,options,answer,explain,points,knowledge,source) VALUES('che-14b','化学','fill','有一瓶密封不严的漂白粉样品，肯定含有 CaCl2。假设①：该漂白粉未变质，含有＿＿；假设②：该漂白粉全部变质，含有＿＿。实验 1：取样加稀盐酸，有气泡产生 → 则假设＿＿不成立；实验 2：向实验 1 反应后的试管中滴加品红溶液，振荡。若品红褪色，结合实验 1 则假设＿＿成立；若品红不褪色，则假设＿＿成立。（假设③：部分变质，既含 Ca(ClO)2 又含 CaCO3）',NULL,'["Ca(ClO)2", "CaCO3", "①||1", "③||3", "②||2"]','漂白粉变质原理：Ca(ClO)2 + CO2 + H2O = CaCO3↓ + 2HClO。实验 1 加稀盐酸有气泡 → 有 CaCO3 → "未变质"的假设①不成立；实验 2 品红褪色 → 还有 Ca(ClO)2（能使品红褪色）→ 部分变质，假设③成立；品红不褪色 → Ca(ClO)2 已耗尽 → 全部变质，假设②成立。',12,'漂白粉变质探究','化学专题练习卷（2026-10-19）');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-01','化学','方程式默写','钠与水反应','2Na + 2H2O = 2NaOH + H2↑','思路：钠是活泼金属，与水剧烈反应生成氢氧化钠和氢气。四步checklist：化学式写对→配平（Na 2个、H2O 2个）→无特殊条件→H2是气体加↑。易错：漏写H2、漏↑。她13-(1)漏写H2且未配平被扣光。','钠,配平,气体符号');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-02','化学','方程式默写','钠在常温下与氧气反应','4Na + O2 = 2Na2O','思路：常温下钠被氧化生成氧化钠。关键：条件决定产物——常温→Na2O，点燃→Na2O2。她11-(1)自创了不明条件“R△”，产物也写错，0分。','钠,条件决定产物');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-03','化学','方程式默写','钠在氧气中燃烧','2Na + O2 = 【条件：点燃】 Na2O2','思路：点燃时生成淡黄色的过氧化钠Na2O2。对比记忆：常温→Na2O，点燃→Na2O2。易错：把Na2O2写成NaO2。','钠,条件,过氧化钠');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-04','化学','方程式默写','过氧化钠与水反应','2Na2O2 + 2H2O = 4NaOH + O2↑','思路：Na2O2中O为-1价，歧化为O2（0价）和OH-中的O（-2价）。配平：先定Na2O2为2，再配H2O为2。易错：漏O2↑。','过氧化钠,配平');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-05','化学','方程式默写','过氧化钠与二氧化碳反应（呼吸面具供氧原理）','2Na2O2 + 2CO2 = 2Na2CO3 + O2','思路：呼吸面具/潜水艇供氧剂原理，CO2→O2。她13-(2)写成Na2O2+CO2=2Na2CO3+O2未配平被扣1分——配平是按规则必扣分的，亲手配10遍。','过氧化钠,配平,13题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-06','化学','方程式默写','碳酸氢钠受热分解','2NaHCO3 = 【条件：加热】 Na2CO3 + CO2↑ + H2O','思路：NaHCO3不稳定，受热分解。配平：2个NaHCO3。易错：漏条件加热、漏↑。','碳酸氢钠,条件');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-07','化学','方程式默写','碳酸钠与足量盐酸反应','Na2CO3 + 2HCl = 2NaCl + CO2↑ + H2O','思路：强酸制弱酸，碳酸盐+酸→CO2↑。她13-(2)这个写对拿了满分，会写的要保持。注意：盐酸少量时先生成NaHCO3，足量才放出CO2。','碳酸钠,气体符号');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-08','化学','方程式默写','铝与盐酸反应','2Al + 6HCl = 2AlCl3 + 3H2↑','思路：Al是活泼金属，与非氧化性酸生成AlCl3和H2。配平：Al 2个、HCl 6个、H2 3个。','铝,配平');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-09','化学','方程式默写','铝与氢氧化钠溶液反应','2Al + 2NaOH + 2H2O = 2NaAlO2 + 3H2↑','思路：Al既能与酸反应又能与强碱反应（两性金属的特性）。产物是偏铝酸钠NaAlO2和H2。配平：Al 2、NaOH 2、H2O 2。易错：漏写H2O、漏↑。','铝,两性,配平');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-10','化学','方程式默写','氧化铝与盐酸反应','Al2O3 + 6HCl = 2AlCl3 + 3H2O','思路：Al2O3是两性氧化物，与酸生成盐和水。配平：HCl 6个。','铝,两性氧化物');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-11','化学','方程式默写','氢氧化铝与氢氧化钠溶液反应','Al(OH)3 + NaOH = NaAlO2 + 2H2O','思路：Al(OH)3是两性氢氧化物，溶于强碱生成偏铝酸钠。注意H2O是2个，配平不要漏。','铝,两性');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-12','化学','方程式默写','铁在氯气中燃烧','2Fe + 3Cl2 = 【条件：点燃】 2FeCl3','思路：Cl2是强氧化剂，把Fe氧化到+3价，生成FeCl3（棕褐色烟）。对比：Fe与盐酸只生成FeCl2+H2↑——她11-(3)把两者混了，还写出Fe3Cl2这种不存在的化学式。记住：氧化剂强弱决定价态，Cl2强→+3价，HCl弱→+2价。','铁,氯气,11题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-13','化学','方程式默写','铁与盐酸反应','Fe + 2HCl = FeCl2 + H2↑','思路：Fe与非氧化性酸反应，Fe只到+2价，生成FeCl2和H2↑。对比记忆：Fe+Cl2→FeCl3，Fe+HCl→FeCl2。','铁,对比');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-14','化学','方程式默写','氯化亚铁溶液中通入氯气','2FeCl2 + Cl2 = 2FeCl3','思路：Cl2把Fe2+氧化为Fe3+，溶液由浅绿色变为棕黄色。这是Fe2+的检验思路之一。','铁,氧化还原');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-15','化学','方程式默写','氢氧化亚铁在空气中被氧化','4Fe(OH)2 + O2 + 2H2O = 4Fe(OH)3','思路：白色Fe(OH)2→灰绿色→红褐色Fe(OH)3。配平：Fe(OH)2 4个、O2 1个、H2O 2个。现象记忆：颜色渐变是考点。','铁,配平,现象');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-16','化学','方程式默写','氧化铁与盐酸反应','Fe2O3 + 6HCl = 2FeCl3 + 3H2O','思路：Fe2O3（铁红）是碱性氧化物，与酸生成盐和水。配平：HCl 6个。','铁');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-17','化学','方程式默写','氢气在氯气中燃烧','H2 + Cl2 = 【条件：点燃】 2HCl','思路：苍白色火焰，生成HCl。她11-(2)涂改混乱得0分——这个式子必须一笔写对：H2+Cl2点燃→2HCl。','氯气,11题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-18','化学','方程式默写','氯气与水反应（氯水的成分）','Cl2 + H2O ⇌ HCl + HClO','思路：可逆反应（⇌）。氯水中含Cl2、HClO、H+、Cl-等。HClO是弱酸，有漂白性。易错：写成等号、漏写HClO。','氯气,可逆,漂白');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-19','化学','方程式默写','次氯酸见光分解','2HClO = 【条件：光照】 2HCl + O2↑','思路：HClO不稳定，见光分解为HCl和O2——这就是氯水要避光保存、新制氯水久置变成稀盐酸的原因。她11-(4)写成HClO=H2O+Cl2↑，产物全错。','氯气,11题错题,光照');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-20','化学','方程式默写','氯气与氢氧化钠溶液反应（尾气吸收）','Cl2 + 2NaOH = NaCl + NaClO + H2O','思路：产物是NaClO（次氯酸钠）不是HClO——她14-(3)写成HClO被扣光。记忆：碱吸收氯气，Cl2歧化为Cl-和ClO-。配平：NaOH 2个。','氯气,14题错题,尾气吸收');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-21','化学','方程式默写','实验室制取氯气','MnO2 + 4HCl(浓） = 【条件：加热】 MnCl2 + Cl2↑ + 2H2O','思路：二氧化锰+浓盐酸加热。四要素缺一不可：MnO2、浓HCl、加热、配平（HCl 4个、H2O 2个）。她14-(1)未配平、缺“浓”和“加热”被扣2分——按规则配平/条件/气体符号有问题各扣1分。','氯气,实验室制法,14题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-22','化学','方程式默写','工业制漂白粉','2Ca(OH)2 + 2Cl2 = CaCl2 + Ca(ClO)2 + 2H2O','思路：氯气通入石灰乳。漂白粉是混合物（CaCl2·Ca(ClO)2），有效成分是Ca(ClO)2——她14-(5)把两者混淆。配平：Ca(OH)2 2个、Cl2 2个、H2O 2个。她11-(5)配平也错了，重默10遍。','氯气,漂白粉,14题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-23','化学','方程式默写','铜与浓硫酸反应（加热）','Cu + 2H2SO4(浓） = 【条件：加热】 CuSO4 + SO2↑ + 2H2O','思路：浓硫酸的强氧化性（+6价S→+4价SO2），Cu被氧化为CuSO4。必须加热、必须浓硫酸。配平：H2SO4 2个。','浓硫酸,氧化性');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-24','化学','方程式默写','碳与浓硫酸反应（加热）','C + 2H2SO4(浓） = 【条件：加热】 CO2↑ + 2SO2↑ + 2H2O','思路：C被浓硫酸氧化为CO2，浓硫酸被还原为SO2。两个气体产物都要加↑。配平：H2SO4 2个、SO2 2个。','浓硫酸,配平');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-25','化学','方程式默写','二氧化硫与水反应','SO2 + H2O ⇌ H2SO3','思路：可逆反应，生成亚硫酸H2SO3（二元弱酸）。SO2是酸性氧化物。','硫,可逆');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-26','化学','方程式默写','氨的催化氧化','4NH3 + 5O2 = 【条件：催化剂、加热】 4NO + 6H2O','思路：工业制硝酸第一步。NH3中N（-3价）→NO中N（+2价）。配平：NH3 4个、O2 5个、NO 4个、H2O 6个。条件催化剂（铂铑合金）+加热缺一不可。','氨,催化氧化,配平');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-27','化学','方程式默写','一氧化氮与氧气反应','2NO + O2 = 2NO2','思路：无色NO遇空气变红棕色NO2，是NO的特征检验。配平：NO 2个、NO2 2个。','氮,现象');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-28','化学','方程式默写','二氧化氮与水反应','3NO2 + H2O = 2HNO3 + NO','思路：NO2与水歧化，生成硝酸和NO。配平：NO2 3个、HNO3 2个。','氮,配平');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-29','化学','方程式默写','二氧化硅与氢氧化钠溶液反应','SiO2 + 2NaOH = Na2SiO3 + H2O','思路：SiO2是酸性氧化物，与碱生成硅酸钠和水。这就是“盛碱液的玻璃瓶不能用玻璃塞”的原因（会生成Na2SiO3把瓶塞粘住）。','硅,酸性氧化物');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('chem-30','化学','方程式默写','二氧化硅与氢氟酸反应','SiO2 + 4HF = SiF4↑ + 2H2O','思路：SiO2的特性——只与HF反应（其他酸都不反应），用于雕刻玻璃。配平：HF 4个，SiF4是气体加↑。','硅,特性');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('pol-01','政治','标志性表述','21题得分点①：奴隶社会代替原始社会是什么性质？','奴隶社会代替原始社会是历史的进步。','21题1分得分点。观点句先写，这是送分的第一句，写完再跟论据。她这句写出来了，要保持。','社会形态更替,21题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('pol-02','政治','标志性表述','21题得分点②：判断社会形态更替是进步还是倒退的主要标准','生产关系一定要适应生产力状况的规律是人类社会发展的一般规律。一种社会形态代替另一种社会形态，究竟是历史的进步还是倒退，判断的主要标准，是看生产关系是否适应生产力的发展要求，是否符合人类社会发展的总趋势。','21题3分得分点。她只写了零散表述丢了分。关键词：生产关系适应生产力、是否符合人类社会发展的总趋势。','历史规律,21题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('pol-03','政治','标志性表述','21题得分点④：奴隶社会进步性的具体表现（三个）','奴隶社会代替原始社会后，金属工具的广泛使用、城市的出现、脑力劳动和体力劳动的分工等，这是历史的进步。','21题3分得分点。她一个论据没写，观点空转。三个关键词必须一字不差：金属工具、城市、脑力劳动和体力劳动的分工。','史实论据,21题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('pol-04','政治','标志性表述','22题得分点①：中华人民共和国成立的意义（“四个彻底结束”＋伟大飞跃）','中华人民共和国的成立，彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了极少数剥削者统治广大劳动人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃。','22题3分得分点。她这题只拿2/8分，关键词全缺。四个“彻底结束”＋“从封建专制政治向人民民主的伟大飞跃”，一字不差背下来。','新中国成立,22题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('pol-05','政治','标志性表述','22题得分点②：新中国成立为过渡创造的前提条件','中华人民共和国的成立，为实现由新民主主义向社会主义的过渡创造了前提条件，从根本上改变了中国社会的发展方向，为实现国家富强、民族复兴展示了美好前景和现实道路。','22题3分得分点。关键词：过渡创造了前提条件、根本上改变发展方向、美好前景和现实道路。','新中国成立,22题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('pol-06','政治','标志性表述','22题得分点③：新中国成立的世界意义','新中国的诞生，冲破了帝国主义的东方战线，极大地改变了世界政治力量的对比，鼓舞和推动了世界被压迫民族和被压迫人民争取解放的斗争。','22题2分得分点。关键词：东方战线、世界政治力量对比、被压迫民族。','新中国成立,22题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('pol-07','政治','标志性表述','23题得分点②：改革开放的地位（“必由之路”“关键一招”）','改革开放是党和人民大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招。','23题4分得分点。她缺了“必由之路/关键一招”丢5分。关键词：重要法宝、必由之路、关键一招（出现两次）。','改革开放,23题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('pol-08','政治','标志性表述','24题骨架：“只有社会主义能救中国”四段论证＋总结句','①在半殖民地半封建社会的近代中国，资本主义道路走不通。②中国共产党的诞生使中国人民有了前进的主心骨，党领导各族人民夺取了新民主主义革命的伟大胜利。③中华人民共和国的成立，从根本上改变了中国社会的发展方向。④社会主义改造的完成，在中国建立起社会主义制度。总之：只有社会主义才能救中国。','24题12分她只拿3分，缺②③两大得分块。先背四段骨架再填肉：旧路不通→党领导革命胜利→新中国转方向→社会主义改造建制度→总结句。','社会主义,24题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-01','地理','概念辨析','大气逆辐射和反射是一回事吗？','不是。反射是太阳辐射被云层、地面直接弹回太空，属于削弱作用；大气逆辐射是大气吸收地面长波辐射后、再以长波辐射形式返还给地面的部分，属于保温作用。','27(2)就栽在这：把“大气逆辐射”写成“反射”，6分只拿1分。记忆钩：逆辐射是“大气回赠给地面的热量”，方向是朝下的。','大气,27题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-02','地理','概念辨析','大气的削弱作用和保温作用各指什么？','削弱作用：大气对太阳辐射的吸收、反射、散射，使到达地面的太阳辐射减少（白天降温）。保温作用：大气吸收地面辐射，并以大气逆辐射形式返还热量给地面（夜间保温）。','28(2)把两者混为一谈，得出“太阳辐射强度与气温成反比”的错误结论，6分挂零。记住：削弱管白天，保温管夜晚。','大气,28题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-03','地理','概念辨析','复述“大气的受热过程”完整链条','太阳辐射→（被大气削弱：吸收/反射/散射）→地面吸收→地面增温→地面辐射（长波）→大气吸收→大气增温→大气逆辐射→返还地面（保温）。根本热源是太阳辐射，直接热源是地面。','27、28题的共同病根，约13分。每天默画一遍这张图，标出削弱三种形式和保温链条，直到闭眼能复述。','大气,链条');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-04','地理','概念辨析','古登堡面、莫霍面的深度和软流层的位置','古登堡面约2900km，是地幔与地核的分界面；莫霍面平均约17km深，是地壳与地幔的分界面；软流层位于上地幔顶部，是岩浆的发源地。','26(1)她把古登堡面写成4000，纯记忆分丢了。2900这个数字贴书桌——这是卷面直接考的。','地球圈层,数字');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-05','地理','概念辨析','太阳大气层由里到外是哪三层？对应的太阳活动是什么？','由里到外：光球层→色球层→日冕层。对应太阳活动：黑子在光球层，耀斑（日珥）在色球层。口诀：黑子在光球，耀斑在色球。','26(3)她这题拿了满分，说明记得住——保持住，别还回去。','太阳,记忆');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-06','地理','概念辨析','对流层气温随高度如何变化？近地面大气的直接热源是什么？','对流层气温随高度升高而降低。近地面大气的主要直接热源是地面（地面辐射），不是太阳直接加热。','26(4)她把“降低”写成“升高”，规律记反丢分。记忆：越高越冷，因为热源在脚下（地面）。','对流层,26题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-07','地理','概念辨析','地质年代：古生代、中生代、新生代和第四纪是什么关系？','古生代、中生代、新生代是“代”；第四纪是新生代里的一个“纪”，层级比代低。','26(2)她把“新生代”等同于“第四纪”，是层级混淆丢2分。记住：代和纪是上下级，第四纪属于新生代。','地质年代,26题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-08','地理','概念辨析','为什么青藏高原“太阳辐射强、气温却低”？','辐射强：①纬度低太阳高度大；②晴天多，削弱作用弱；③海拔高空气稀薄，削弱作用弱。气温低：④空气稀薄，大气吸收地面辐射少，保温作用弱。','28(2)她只答出②③，还推出“成反比”的错误结论，6分挂零。记住：辐射强弱看“削弱”，气温高低看“保温”，两套逻辑别串。','青藏高原,28题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-09','生物','概念辨析','病毒有细胞结构吗？蓝藻呢？','病毒无细胞结构（只有蛋白质外壳+核酸）；蓝藻是原核细胞生物，有细胞结构（无核膜、无叶绿体）。','21-(1)她疑似写成“无细胞结构”得0分——题干问的是有细胞结构的生物，别把病毒和蓝藻搞反。','细胞,21题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-10','生物','概念辨析','区分原核细胞和真核细胞的根本标准是什么？','有无以核膜为界限的细胞核。有→真核细胞，无→原核细胞（如细菌、蓝藻）。','21-(2)她这个答对了。根本标准只有一个：核膜。','细胞');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-11','生物','概念辨析','蓝藻含有什么色素？有叶绿体吗？','蓝藻含有藻蓝素和叶绿素，能进行光合作用，但没有叶绿体（原核生物没有叶绿体、线粒体等复杂细胞器）。','21-(3)她写成“叶绿体”得0分——典型易错点：有叶绿素≠有叶绿体。','蓝藻,21题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-12','生物','概念辨析','自由水和结合水有什么区别？','自由水：游离态，可自由流动，是良好溶剂、参与化学反应、运输物质；结合水：与细胞内其他物质结合，是细胞结构的重要组成成分。代谢越旺盛，自由水与结合水的比值越高。','22题连丢6分：自由水功能（良好溶剂）没写出来。记住：自由水管“活”（代谢），结合水管“结构”。','水,22题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-13','生物','概念辨析','蛋白质计算三公式','①脱水数＝氨基酸数－肽链数；②蛋白质相对分子质量＝氨基酸总分子质量－18×脱水数；③一条肽链至少含1个游离氨基和1个游离羧基。','23题她脱水数直接写51（氨基酸总数），正确是51-2=49；分子量882 vs 888漏项。这三公式默到条件反射。','蛋白质,23题错题,公式');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-14','生物','概念辨析','画出氨基酸的结构通式','中心碳原子上连接：一个氨基（-NH2）、一个羧基（-COOH）、一个氢原子（-H）、一个R基。结构式：H2N—C(R)(H)—COOH。','23-(1)她用文字描述代替画图得0分——题目要求画图就必须画，文字描述不给分。亲手画50遍。','氨基酸,23题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-15','生物','概念辨析','斐林试剂检测还原糖的关键条件和现象是什么？','条件：水浴加热（50-65℃）。现象：出现砖红色沉淀。','24-(1)她写“没有加热”得0分——“水浴”是关键限定词，直接加热不行。实验题先圈限定词。','实验,24题错题');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-16','英语','概念辨析','Although和but能连用吗？','不能。Although本身已表转折，再加but重复。改法：Although he is tired, he keeps working. 或 He is tired, but he keeps working.','作文硬伤第1条：Although play computer games can…, but it…——although和but连用是典型中式错误，见到就改。','英语,作文,连词');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-17','英语','概念辨析','advice可数吗？','不可数。a piece of advice（一则建议），不能说advices。','作文：follow my advices→follow my advice。不可数名词没有复数形式。','英语,作文,名词');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-18','英语','概念辨析','it is not a good things对吗？','不对。a是单数冠词，后面必须跟单数：it is not a good thing。单复数必须一致：a thing / good things。','作文硬伤：a good things——冠词a和复数things打架。写完检查：a/an后面一定是单数。','英语,作文,单复数');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-19','英语','概念辨析','stop doing和stop to do有什么区别？forget呢？','stop doing：停止正在做的事（Stop playing games.）；stop to do：停下来去做另一件事。forget doing：忘记做过的事；forget to do：忘记去做（还没做）。','作文：stop play→stop playing；don''t forget do→don''t forget to do。先判断“这件事做没做”，再选doing/to do。','英语,作文,非谓语');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('con-20','英语','概念辨析','have confidence in后面跟什么词形？','跟名词：have confidence in sb/sth（对……有信心）。confident是形容词（be confident of/about），confidence是名词。','完成句子66题：have confidence in后面写了confident（形容词）得0分。in是介词，后面只能跟名词/动名词。','英语,词形');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-01','英语','词句急救','have ______ in（对……有信心）','have confidence in','66题错：写了confident（形容词）。in是介词，后面跟名词confidence。整句：We should have confidence in ourselves.','词形,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-02','英语','词句急救','The movie is ______（令人困惑的）','confusing','67题0分。-ing形容词修饰物（令人……的），-ed形容词修饰人（感到……的）：confusing movie / confused person。','形容词,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-03','英语','词句急救','He runs ______（极其）fast','extremely','68题0分。副词修饰形容词/副词：extremely fast。extreme是形容词，不能直接修饰fast。','副词,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-04','英语','词句急救','be ______ to games（沉迷于游戏）','be addicted to','72题0分，目标短语直接不会。addicted是形容词：be addicted to sth/doing sth（沉迷于……）。','短语,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-05','英语','词句急救','______ than watching TV（除了看电视之外）','other than','75题0分。other than＝除了……之外。注意than的拼写。','短语,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-06','英语','词句急救','______ up the room（打扫房间）','clean up','73题部分给分。clean up＝打扫干净，up是副词不是介词。','短语,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-07','英语','词句急救','______ control of the company（接管公司）','take control of / took control of','74题部分给分。take control of＝控制、接管，注意时态用took。','短语,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-08','英语','词句急救','______ on your study（专注于学习）','concentrate on / focus on','76题部分给分。concentrate on＝focus on＝专注于，后面跟名词/动名词。','短语,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-09','英语','词句急救','leave the baby ______（别管婴儿，让他自己待着）','leave alone','70题全对。leave sb alone＝别打扰某人，让某人独自待着。','短语,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-10','英语','词句急救','look ______ to hearing from you（期待收到你的来信）','look forward to','71题全对。look forward to中to是介词，后面跟名词/动名词：look forward to hearing from you。','短语,完成句子');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-11','英语','词句急救','______ reduce stress, he runs daily.（为了减压）','to reduce','57题错写成to surprised。不定式to do表目的，后面必须跟动词原形：to reduce（为了减少）。','不定式,语法填空');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-12','英语','词句急救','This book is ______（更容易）than that one','easier','59题未写出完整形式。easy→easier，比较级变化：y变i加er。','比较级,语法填空');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-13','英语','词句急救','______ children are playing there.（那些孩子，特指）','the','63题0分。特指双方都知道的人/物用the：the children＝那些孩子们。','冠词,语法填空');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-14','英语','词句急救','______ children aged 5-10（5-10岁的孩子们）','aged','64题0分。aged是age的过去分词作定语：children aged 5-10＝5到10岁的孩子们。','分词,语法填空');
INSERT INTO dictation(id,subject,set_name,prompt,answer,explain,tags) VALUES('eng-15','英语','词句急救','______ children, playing outside is fun.（对于孩子们来说）','For','56题错写成at。句首表对象/范围用For：For children, …＝对于孩子们来说。','介词,语法填空');
