INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('历史','21(1)',4.0,4.0,'（手写，辨认见下）','任答两点：王室衰微；宗法松弛；诸侯坐大；争霸战争；生产力发展/井田瓦解；分封制缺陷','','分封制瓦解的原因。踩中：王室衰微、诸侯世袭坐大、诸侯争霸、不听王命','');
INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('历史','21(2)',8.0,3.0,'（手写，辨认见下）','背景：商鞅变法推行县制；秦统一六国；法家思想确立。意义：强化中央集权；促进地区交流；贵族政治→官僚政治；后世地方治理基本制度','表述不规范/知识盲区','郡县制推行的背景与意义。背景只写"战国变法"太笼统，未点名商鞅变法/县制/秦统一/法家思想；意义答出"集权、收归地方权力"，但"为秦统一奠定基础"因果倒置（郡县制是统一后推行）','');
INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('历史','22(1)',6.0,2.0,'（手写，辨认见下）','任答三点：圩田/闸坝灌溉体系；开田万顷；岁增粟帛；耕作效率提高','表述不规范','江南农业发展的表现。未用关键词（圩田、灌溉体系、开田万顷、岁增粟帛），表述混乱','');
INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('历史','22(2)',6.0,2.0,'（手写，辨认见下）','任答三点：北民南迁；曲辕犁/龙骨水车/圩田水利；土断/赋税改革/漕运；政府重视水利','知识盲区/表述不规范','江南农业发展的主要因素。自编"气候适宜"非得分点；"北民南迁/朝廷重视"方向对但缺关键词（曲辕犁、土断、漕运）','');
