INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('历史','23',12.0,6.0,'（手写，辨认见下）','主题(3)+三部分标题(3×1)+内容方向(3×2)：背景/学派人物主张/历史影响','审题偏差/表述不规范','百家争鸣。三段结构完整；背景、学派部分部分踩点；第三部分写"秦统一终结百家争鸣（焚书坑儒）"，偏离"对后世文化与治理的实践价值"得分方向；主题句潦草难辨','');
