INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('政治','21',10.0,4.0,'（手写，辨认见下）','①是历史进步(1)+②生产关系适应生产力规律/判断标准(3)+③原始社会末期阻碍生产力、奴隶制组织大协作(3)+④金属工具/城市/脑体分工(3)','表述不规范/知识盲区','奴隶社会代替原始社会的进步性。答出"历史进步"+"生产力被束缚/相适应"等零散表述；缺"金属工具、城市出现、脑体分工"等具体史实得分点，未展开论证','');
INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('政治','22',8.0,2.0,'（手写，辨认见下）','①四个"彻底结束"+伟大飞跃(3)+②过渡前提/改变发展方向/展示前景(3)+③东方战线/世界政治力量对比/鼓舞被压迫民族(2)','知识盲区/表述不规范','新中国成立的意义。未用关键词（彻底结束、半殖民地半封建、人民民主、过渡前提、东方战线），表述空泛','');
INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('政治','23',10.0,5.0,'（手写，辨认见下）','①四个面貌+三个飞跃(4)+②必由之路/关键一招(4)+③只有进行时/活力之源(2)','知识盲区（部分）','改革开放的意义。答出"四个面貌/三个飞跃"和"活力之源"；缺"必由之路/关键一招"表述','');
INSERT INTO mistakes(subject,question_no,full_score,got_score,student_answer,std_answer,error_type,knowledge_point,note) VALUES('政治','24',12.0,3.0,'（手写，辨认见下）','①资本主义道路走不通(3)+②党的诞生与新民主主义革命胜利(3)+③新中国成立改变发展方向(3)+④社会主义改造完成(3)+总结句','知识盲区/表述不规范','只有社会主义能救中国。只有"资本主义走不通"+"一化三改/社会主义改造"+总结句碎片；缺"党的诞生与新民主主义革命胜利""新中国成立改变发展方向"两大得分块','');
